import{_ as r,o as a,c as t,a4 as l}from"./chunks/framework.2-Vke5-n.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"Terraform設計ガイドライン","tagline":"Terraform Design Guidelines","actions":[{"theme":"brand","text":"Terraform設計ガイドライン","link":"./terraform_guidelines.md"}]}},"headers":[],"relativePath":"documents/forTerraform/index.md","filePath":"documents/forTerraform/index.md"}'),o={name:"documents/forTerraform/index.md"};function i(n,e,s,d,c,f){return a(),t("div",null,[...e[0]||(e[0]=[l('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>Terraformはインフラを宣言的にコード管理するツールであるが、特に大規模なシステムでは扱うリソース数が増え、必然的にTerraformコードも複雑化する傾向にある。Terraformの可読性が低下すると、作業効率の低下だけではなく影響度が大きいミスを誘発する懸念がある。</p><p>また、Terraformは活発に機能開発が継続されており新しい機能／記述方法もリリース毎に追加されている。これは嬉しい反面、新規開発者が悩むポイントも増えたと言える。関連して、チームやプロジェクトごとに設計方針が異なる場合も多く、Terraformの熟練者であってもそれぞれのコードベースに慣れるまで時間を要することも往々にしてある。</p><p>本ガイドラインは、各開発者が悩むポイントを軽減し、可読性や保守性、安全性を高めるルールをまとめ、設計のベースラインとするために作成された。それにより、生産性の向上・レビュー負荷の軽減・ナレッジやツールの横展開の支援・技術レベルの底上げを目指すものとする。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h2><p>対象とする技術は以下を想定している。</p><ul><li>Terraform 1.10+</li><li>OSS利用のみ（HCP Terraformは利用しない）</li><li>AWS、Google Cloud、Azureなどのクラウドサービスに対しての利用</li></ul><p>利用者は以下の技術を理解しているとし、本ガイドラインではこれらについて解説はしない。</p><ul><li>基本的なTerraformの知識と理解</li><li>Gitの基本的な知識</li><li>CI/CDの基本的な知識</li></ul><p>本ガイドラインの適用範囲は、Terraformの設計、開発時に利用することを想定している。クラウドサービス上の技術選定、サービス設計の手法については本ガイドラインで対象外とする。</p><h2 id="用語定義" tabindex="-1">用語定義 <a class="header-anchor" href="#用語定義" aria-label="Permalink to &quot;用語定義&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">ルートモジュール</td><td style="text-align:left;">terraformコマンドを実行するディレクトリ上にある .tf リソース</td></tr><tr><td style="text-align:left;">モジュール</td><td style="text-align:left;">本ガイドラインでは、ルートモジュールから利用される子モジュールのことを指す</td></tr></tbody></table><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://cloud.google.com/docs/terraform/best-practices-for-terraform?hl=ja" target="_blank" rel="noreferrer">Terraform を使用するためのベスト プラクティス | Google Cloud</a></li><li><a href="https://docs.aws.amazon.com/ja_jp/prescriptive-guidance/latest/terraform-aws-provider-best-practices/structure.html" target="_blank" rel="noreferrer">コードベースの構造と組織のベストプラクティス - AWS 規範ガイダンス</a></li><li><a href="https://zenn.dev/coconala/articles/create_code_policy" target="_blank" rel="noreferrer">最低限のTerraformコード規約を定義した | Zenn</a></li></ul><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、牛田隆之、前原応光、伊藤太斉、金澤祐輔、天明昂輝、神崎林太郎</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.04.09 <a href="https://future-architect.github.io/articles/20250409a/" target="_blank" rel="noreferrer">Terraform設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./terraform_guidelines.html">Terraform設計ガイドライン</a></p></div>',21)])])}const u=r(o,[["render",i]]);export{m as __pageData,u as default};
